pm.collectionVariables.set('tokenA', body.refreshToken);
pm.collectionVariables.unset('tokenB');

pm.test('Login through Gateway 1 returns 200', function () { pm.response.to.have.status(200); });
const body = pm.response.json();
pm.test('Login response contains accessToken', function () { pm.expect(body.accessToken).to.be.a('string').and.not.empty; });
pm.collectionVariables.set('gatewayAccessToken', body.accessToken);

pm.test('Login returns 200', function () { pm.response.to.have.status(200); });
const body = pm.response.json();
pm.test('Login contains an access token', function () { pm.expect(body.accessToken).to.be.a('string').and.not.empty; });
pm.collectionVariables.set('productAccessToken', body.accessToken);
pm.collectionVariables.unset('productId');
pm.collectionVariables.unset('productSku');

pm.test('Product creation returns 201', function () { pm.response.to.have.status(201); });
const body = pm.response.json();
pm.test('Response uses the shared success envelope', function () { pm.expect(body.success).to.eql(true); });
pm.test('Created product has an id, expected SKU, and active status', function () {
  pm.expect(body.data.id).to.be.a('string').and.not.empty;
  pm.expect(body.data.sku).to.eql(pm.collectionVariables.get('productSku'));
  pm.expect(body.data.active).to.eql(true);
});
pm.collectionVariables.set('productId', body.data.id);

pm.test('Product lookup returns 200', function () { pm.response.to.have.status(200); });
const body = pm.response.json();
pm.expect(body.data.id).to.eql(pm.collectionVariables.get('productId'));
pm.expect(body.data.sku).to.eql(pm.collectionVariables.get('productSku'));

pm.test('Category listing returns 200', function () { pm.response.to.have.status(200); });
const body = pm.response.json();
pm.test('Category listing includes the created product', function () {
  pm.expect(body.data.some(function (product) { return product.id === pm.collectionVariables.get('productId'); })).to.eql(true);
});

pm.test('Product update returns 200', function () { pm.response.to.have.status(200); });
const body = pm.response.json();
pm.expect(body.data.id).to.eql(pm.collectionVariables.get('productId'));
pm.expect(body.data.name).to.eql('Postman Catalog Test Updated');
pm.expect(Number(body.data.price)).to.eql(24.99);

pm.test('Soft-deleted product remains retrievable', function () { pm.response.to.have.status(200); });
const body = pm.response.json();
pm.expect(body.data.id).to.eql(pm.collectionVariables.get('productId'));
pm.expect(body.data.active).to.eql(false);

pm.test('Active category listing returns 200', function () { pm.response.to.have.status(200); });
const body = pm.response.json();
pm.test('Soft-deleted product is omitted from active listings', function () {
  pm.expect(body.data.some(function (product) { return product.id === pm.collectionVariables.get('productId'); })).to.eql(false);
});

pm.test('Registration returns 201 Created', function () { pm.response.to.have.status(201); });
const body = pm.response.json();
pm.test('Registration returns a user id and requested email', function () {
  pm.expect(body.userId).to.be.a('string').and.not.empty;
  pm.expect(body.email).to.eql(pm.variables.get('email'));
});
pm.test('Registration returns the supplied name fields', function () {
  pm.expect(body.firstName).to.eql('Postman');
  pm.expect(body.lastName).to.eql('Tester');
});
pm.collectionVariables.set('registeredUserId', body.userId);
pm.collectionVariables.set('registeredEmail', body.email);

