pm.test('Inventory lookup returns 200', function () { pm.response.to.have.status(200); });
const data = pm.response.json().data;
pm.expect(data.onHand).to.eql(10);
pm.expect(data.reserved).to.eql(0);
pm.expect(data.available).to.eql(10);

pm.test('Reservation returns 201', function () { pm.response.to.have.status(201); });
